-- SCIT DPP - esquema inicial. Ejecutar en Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('director','coordinador','administrativo','lectura');
create type public.slot_status as enum ('VACANTE','EN_GESTION','CUBIERTO','SUSPENDIDO');
create type public.term_kind as enum ('INICIAL_12','RENOVACION_6');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role app_role not null default 'lectura', active boolean not null default true, created_at timestamptz default now());
create table public.internship_slots(id uuid primary key default gen_random_uuid(), code text unique not null check(code ~ '^[SR][0-9]{2}$'), city text not null check(city in ('Santa Fe','Rosario')), status slot_status not null default 'VACANTE', office text, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.interns(id uuid primary key default gen_random_uuid(), full_name text not null, dni text, email text, phone text, university text, academic_unit text, career text, notes text, created_at timestamptz default now());
create table public.normative_acts(id uuid primary key default gen_random_uuid(), act_type text not null, number text, year int, title text, act_date date, file_number text, url text, notes text, created_at timestamptz default now());
create table public.internship_assignments(id uuid primary key default gen_random_uuid(), slot_id uuid not null references internship_slots(id), intern_id uuid not null references interns(id), status text not null default 'ACTIVA', start_date date not null, end_date date not null, ended_at date, designation_act_id uuid references normative_acts(id), vacancy_act_id uuid references normative_acts(id), call_act_id uuid references normative_acts(id), predecessor_assignment_id uuid references internship_assignments(id), office text, tutor text, notes text, created_at timestamptz default now(), check(end_date>=start_date));
create table public.internship_terms(id uuid primary key default gen_random_uuid(), assignment_id uuid not null references internship_assignments(id) on delete cascade, kind term_kind not null, start_date date not null, end_date date not null, agreement_number text, act_id uuid references normative_acts(id), notes text, created_at timestamptz default now());
create table public.projects(id uuid primary key default gen_random_uuid(), name text not null, description text, area text, responsible text, status text not null default 'PLANIFICACION', progress int not null default 0 check(progress between 0 and 100), start_date date, target_date date, budget numeric(14,2), risk text, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.project_milestones(id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, title text not null, due_date date, completed_at date, status text default 'PENDIENTE', notes text);
create table public.communication_items(id uuid primary key default gen_random_uuid(), title text not null, item_type text, channel text, audience text, responsible text, status text not null default 'PLANIFICADO', target_date date, published_at timestamptz, approval_by text, links text, notes text, created_at timestamptz default now());
create table public.audit_log(id bigint generated always as identity primary key, user_id uuid, table_name text not null, record_id text, action text not null, payload jsonb, created_at timestamptz default now());
-- 47 cupos fijos
insert into public.internship_slots(code,city) select 'S'||lpad(i::text,2,'0'),'Santa Fe' from generate_series(1,24)i on conflict do nothing;
insert into public.internship_slots(code,city) select 'R'||lpad(i::text,2,'0'),'Rosario' from generate_series(1,23)i on conflict do nothing;
-- Validación: máximo 12 meses inicial y 6 renovación; máximo acumulado 18 meses se controla por trigger.
create or replace function public.validate_internship_term() returns trigger language plpgsql as $$ declare total_days int; begin if new.kind='INICIAL_12' and new.end_date>new.start_date+interval '12 months' then raise exception 'Convenio inicial no puede superar 12 meses'; end if; if new.kind='RENOVACION_6' and new.end_date>new.start_date+interval '6 months' then raise exception 'Renovación no puede superar 6 meses'; end if; select coalesce(sum(end_date-start_date+1),0)+(new.end_date-new.start_date+1) into total_days from internship_terms where assignment_id=new.assignment_id and id<>new.id; if total_days>550 then raise exception 'La permanencia total no puede superar aproximadamente 18 meses'; end if; return new; end $$;
create trigger trg_validate_term before insert or update on internship_terms for each row execute function validate_internship_term();
create view public.internship_alerts as select a.id assignment_id,s.code,s.city,i.full_name,a.end_date,(a.end_date-current_date) days_remaining,case when a.end_date-current_date<=30 then 'CRITICA' when a.end_date-current_date<=60 then 'ALTA' when a.end_date-current_date<=90 then 'MEDIA' when a.end_date-current_date<=120 then 'PREAVISO' else 'OK' end alert_level from internship_assignments a join internship_slots s on s.id=a.slot_id join interns i on i.id=a.intern_id where a.status='ACTIVA';
-- RLS
alter table profiles enable row level security; alter table internship_slots enable row level security; alter table interns enable row level security; alter table normative_acts enable row level security; alter table internship_assignments enable row level security; alter table internship_terms enable row level security; alter table projects enable row level security; alter table project_milestones enable row level security; alter table communication_items enable row level security;
create or replace function public.my_role() returns app_role language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid() and active=true $$;
create policy read_slots on internship_slots for select to authenticated using(true); create policy write_slots on internship_slots for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy read_interns on interns for select to authenticated using(true); create policy write_interns on interns for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy read_acts on normative_acts for select to authenticated using(true); create policy write_acts on normative_acts for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy read_assignments on internship_assignments for select to authenticated using(true); create policy write_assignments on internship_assignments for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy read_terms on internship_terms for select to authenticated using(true); create policy write_terms on internship_terms for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy read_projects on projects for select to authenticated using(true); create policy write_projects on projects for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy read_milestones on project_milestones for select to authenticated using(true); create policy write_milestones on project_milestones for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy read_comms on communication_items for select to authenticated using(true); create policy write_comms on communication_items for all to authenticated using(my_role() in ('director','coordinador','administrativo')) with check(my_role() in ('director','coordinador','administrativo'));
create policy profile_self on profiles for select to authenticated using(id=auth.uid() or my_role()='director');
